<script setup>
import {ref,onMounted} from 'vue';import {useRoute,RouterLink,useRouter} from 'vue-router';import {supabase} from '../services/supabase';import AppShell from '../components/AppShell.vue';
const route=useRoute(),router=useRouter(),job=ref(null),loading=ref(true),saved=ref(false),applied=ref(false),cover=ref(''),busy=ref(false),message=ref('');onMounted(async()=>{const {data:{user}}=await supabase.auth.getUser();const {data}=await supabase.from('jobs').select('*, employer:profiles!jobs_employer_id_fkey(full_name,company_name,location,bio,verification_status)').eq('id',route.params.id).single();job.value=data;loading.value=false;if(user&&data){const [s,a]=await Promise.all([supabase.from('saved_jobs').select('job_id').eq('job_id',data.id).eq('student_id',user.id).maybeSingle(),supabase.from('applications').select('id').eq('job_id',data.id).eq('student_id',user.id).maybeSingle()]);saved.value=!!s.data;applied.value=!!a.data}});async function toggleSave(){const {data:{user}}=await supabase.auth.getUser();if(saved.value){await supabase.from('saved_jobs').delete().eq('job_id',job.value.id).eq('student_id',user.id);saved.value=false}else{await supabase.from('saved_jobs').insert({job_id:job.value.id,student_id:user.id});saved.value=true}}async function apply(){busy.value=true;message.value='';const {data:{user}}=await supabase.auth.getUser();const {error}=await supabase.from('applications').insert({job_id:job.value.id,student_id:user.id,cover_letter:cover.value.trim()||null});if(error)message.value=error.code==='23505'?'You have already applied for this job.':error.message;else{applied.value=true;message.value='Application submitted. You can track its progress in My applications.'}busy.value=false}
</script>
<template><AppShell title="Job details" subtitle="Review the opportunity"><template #default><div v-if="loading" class="empty">Loading job details…</div><div v-else-if="!job" class="empty">This job could not be found. <RouterLink to="/jobs">Browse jobs</RouterLink></div><div v-else><RouterLink to="/jobs" class="muted">← Back to jobs</RouterLink><div class="detail-layout" style="margin-top:18px"><article class="card"><div class="job-meta"><span class="badge green">{{job.job_type}}</span><span class="badge">{{job.category}}</span><span>{{job.location}}</span></div><h1 class="page-title" style="margin-top:18px">{{job.title}}</h1><p class="muted">{{job.employer?.company_name||job.employer?.full_name||'Local employer'}} · Posted {{new Date(job.created_at).toLocaleDateString('en-ZA')}}</p><hr><h3>About this opportunity</h3><p class="long-copy">{{job.description}}</p><h3>What we're looking for</h3><p class="long-copy">{{job.requirements||'Please contact the employer for further requirements.'}}</p><div class="grid grid-2"><div><b>Work arrangement</b><p class="muted">{{job.work_mode||'Not specified'}}</p></div><div><b>Hours</b><p class="muted">{{job.hours_per_week?`${job.hours_per_week} hours per week`:'Discussed with employer'}}</p></div><div><b>Closing date</b><p class="muted">{{job.closing_date?new Date(job.closing_date).toLocaleDateString('en-ZA'):'Open until filled'}}</p></div><div><b>Pay</b><p class="muted">{{job.pay_amount?`R${job.pay_amount} ${job.pay_period||''}`:'Pay discussed'}}</p></div></div></article><aside class="card apply-card"><span class="eyebrow">READY TO TAKE THE NEXT STEP?</span><h2>{{job.pay_amount?`R${job.pay_amount}`:'Pay discussed'}} <small>{{job.pay_period==='hourly'?'/ hour':''}}</small></h2><p class="muted">{{job.location}} · {{job.job_type}}</p><div v-if="message" class="alert" :class="applied?'success':'error'">{{message}}</div><form v-if="!applied" @submit.prevent="apply"><div class="field"><label>Short introduction (optional)</label><textarea v-model="cover" class="input" placeholder="Tell the employer why you're a good fit…"></textarea></div><button class="btn btn-primary" style="width:100%" :disabled="busy">{{busy?'Submitting…':'Apply for this job'}}</button></form><div v-else class="alert success">✓ Application submitted</div><button class="btn btn-outline" style="width:100%;margin-top:10px" @click="toggleSave">{{saved?'♥ Saved':'♡ Save this job'}}</button><hr><b>About the employer</b><p class="muted">{{job.employer?.company_name||job.employer?.full_name}} <span v-if="job.employer?.verification_status==='verified'" class="verified">✓ Verified employer</span></p><p class="muted">{{job.employer?.bio||'Employer on Campus Gig'}}</p></aside></div></div></template></AppShell></template>
<style scoped>.detail-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:18px}.detail-layout h3{margin-top:26px}.long-copy{white-space:pre-line;line-height:1.8;color:var(--muted);font-size:14px}.apply-card{height:max-content;position:sticky;top:95px}.apply-card h2{font-size:28px;margin:15px 0 5px;color:var(--navy)}:root[data-theme='dark'] .apply-card h2{color:var(--text)}.apply-card h2 small{font-size:12px}.verified{display:inline-block;background:#dcfce7;color:#166534;border-radius:20px;padding:3px 8px;font-size:10px;font-weight:800}.apply-card hr,.detail-layout hr{border:0;border-top:1px solid var(--border);margin:20px 0}@media(max-width:850px){.detail-layout{grid-template-columns:1fr}.apply-card{position:static}}</style>
